base.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_subnets" "s" {}
resource "terraform_data" "t" {
  input = "x"
}
locals {
  subnet = data.aws_subnets.s.ids[0]
}
resource "aws_ssm_parameter" "p" {
  name  = "p"
  type  = "String"
  value = "%{ if terraform_data.t.output == "x" }${local.subnet}%{ endif }"
}

